PRAGMA foreign_keys=OFF;
BEGIN TRANSACTION;
CREATE TABLE IF NOT EXISTS "django_migrations" ("id" integer NOT NULL PRIMARY KEY AUTOINCREMENT, "app" varchar(255) NOT NULL, "name" varchar(255) NOT NULL, "applied" datetime NOT NULL);
CREATE TABLE IF NOT EXISTS "auth_group_permissions" ("id" integer NOT NULL PRIMARY KEY AUTOINCREMENT, "group_id" integer NOT NULL REFERENCES "auth_group" ("id") DEFERRABLE INITIALLY DEFERRED, "permission_id" integer NOT NULL REFERENCES "auth_permission" ("id") DEFERRABLE INITIALLY DEFERRED);
CREATE TABLE IF NOT EXISTS "auth_user_groups" ("id" integer NOT NULL PRIMARY KEY AUTOINCREMENT, "user_id" integer NOT NULL REFERENCES "auth_user" ("id") DEFERRABLE INITIALLY DEFERRED, "group_id" integer NOT NULL REFERENCES "auth_group" ("id") DEFERRABLE INITIALLY DEFERRED);
CREATE TABLE IF NOT EXISTS "auth_user_user_permissions" ("id" integer NOT NULL PRIMARY KEY AUTOINCREMENT, "user_id" integer NOT NULL REFERENCES "auth_user" ("id") DEFERRABLE INITIALLY DEFERRED, "permission_id" integer NOT NULL REFERENCES "auth_permission" ("id") DEFERRABLE INITIALLY DEFERRED);
CREATE TABLE IF NOT EXISTS "django_admin_log" ("id" integer NOT NULL PRIMARY KEY AUTOINCREMENT, "object_id" text NULL, "object_repr" varchar(200) NOT NULL, "action_flag" smallint unsigned NOT NULL CHECK ("action_flag" >= 0), "change_message" text NOT NULL, "content_type_id" integer NULL REFERENCES "django_content_type" ("id") DEFERRABLE INITIALLY DEFERRED, "user_id" integer NOT NULL REFERENCES "auth_user" ("id") DEFERRABLE INITIALLY DEFERRED, "action_time" datetime NOT NULL);
CREATE TABLE IF NOT EXISTS "django_content_type" ("id" integer NOT NULL PRIMARY KEY AUTOINCREMENT, "app_label" varchar(100) NOT NULL, "model" varchar(100) NOT NULL);
CREATE TABLE IF NOT EXISTS "auth_permission" ("id" integer NOT NULL PRIMARY KEY AUTOINCREMENT, "content_type_id" integer NOT NULL REFERENCES "django_content_type" ("id") DEFERRABLE INITIALLY DEFERRED, "codename" varchar(100) NOT NULL, "name" varchar(255) NOT NULL);
CREATE TABLE IF NOT EXISTS "auth_group" ("id" integer NOT NULL PRIMARY KEY AUTOINCREMENT, "name" varchar(150) NOT NULL UNIQUE);
CREATE TABLE IF NOT EXISTS "auth_user" ("id" integer NOT NULL PRIMARY KEY AUTOINCREMENT, "password" varchar(128) NOT NULL, "last_login" datetime NULL, "is_superuser" bool NOT NULL, "username" varchar(150) NOT NULL UNIQUE, "last_name" varchar(150) NOT NULL, "email" varchar(254) NOT NULL, "is_staff" bool NOT NULL, "is_active" bool NOT NULL, "date_joined" datetime NOT NULL, "first_name" varchar(150) NOT NULL);
CREATE TABLE IF NOT EXISTS "core_keyword" ("id" integer NOT NULL PRIMARY KEY AUTOINCREMENT, "name" varchar(120) NOT NULL UNIQUE);
CREATE TABLE IF NOT EXISTS "core_tag" ("id" integer NOT NULL PRIMARY KEY AUTOINCREMENT, "name" varchar(120) NOT NULL UNIQUE, "description" text NULL);
CREATE TABLE IF NOT EXISTS "core_keywordvalue" ("id" integer NOT NULL PRIMARY KEY AUTOINCREMENT, "value" varchar(255) NOT NULL, "keyword_id" bigint NOT NULL REFERENCES "core_keyword" ("id") DEFERRABLE INITIALLY DEFERRED);
CREATE TABLE IF NOT EXISTS "core_collection_keywords" ("id" integer NOT NULL PRIMARY KEY AUTOINCREMENT, "collection_id" bigint NOT NULL REFERENCES "core_collection" ("id") DEFERRABLE INITIALLY DEFERRED, "keywordvalue_id" bigint NOT NULL REFERENCES "core_keywordvalue" ("id") DEFERRABLE INITIALLY DEFERRED);
CREATE TABLE IF NOT EXISTS "core_biobank_keywords" ("id" integer NOT NULL PRIMARY KEY AUTOINCREMENT, "biobank_id" bigint NOT NULL REFERENCES "core_biobank" ("id") DEFERRABLE INITIALLY DEFERRED, "keywordvalue_id" bigint NOT NULL REFERENCES "core_keywordvalue" ("id") DEFERRABLE INITIALLY DEFERRED);
CREATE TABLE IF NOT EXISTS "core_researchgroup" ("id" integer NOT NULL PRIMARY KEY AUTOINCREMENT, "name" varchar(200) NOT NULL UNIQUE, "description" text NULL, "created_at" datetime NOT NULL, "coordinator_id" integer NOT NULL REFERENCES "auth_user" ("id") DEFERRABLE INITIALLY DEFERRED);
CREATE TABLE IF NOT EXISTS "core_researchgroup_members" ("id" integer NOT NULL PRIMARY KEY AUTOINCREMENT, "researchgroup_id" bigint NOT NULL REFERENCES "core_researchgroup" ("id") DEFERRABLE INITIALLY DEFERRED, "user_id" integer NOT NULL REFERENCES "auth_user" ("id") DEFERRABLE INITIALLY DEFERRED);
CREATE TABLE IF NOT EXISTS "core_sample_tags" ("id" integer NOT NULL PRIMARY KEY AUTOINCREMENT, "sample_id" bigint NOT NULL REFERENCES "core_sample" ("id") DEFERRABLE INITIALLY DEFERRED, "tag_id" bigint NOT NULL REFERENCES "core_tag" ("id") DEFERRABLE INITIALLY DEFERRED);
CREATE TABLE IF NOT EXISTS "core_event" ("id" integer NOT NULL PRIMARY KEY AUTOINCREMENT, "event_type" varchar(50) NOT NULL, "timestamp" datetime NOT NULL, "notes" text NULL, "performed_by_id" integer NULL REFERENCES "auth_user" ("id") DEFERRABLE INITIALLY DEFERRED, "sample_id" bigint NOT NULL REFERENCES "core_sample" ("id") DEFERRABLE INITIALLY DEFERRED, "location_snapshot" varchar(255) NULL);
CREATE TABLE IF NOT EXISTS "core_collection_tags" ("id" integer NOT NULL PRIMARY KEY AUTOINCREMENT, "collection_id" bigint NOT NULL REFERENCES "core_collection" ("id") DEFERRABLE INITIALLY DEFERRED, "tag_id" bigint NOT NULL REFERENCES "core_tag" ("id") DEFERRABLE INITIALLY DEFERRED);
CREATE TABLE IF NOT EXISTS "core_biobank_tags" ("id" integer NOT NULL PRIMARY KEY AUTOINCREMENT, "biobank_id" bigint NOT NULL REFERENCES "core_biobank" ("id") DEFERRABLE INITIALLY DEFERRED, "tag_id" bigint NOT NULL REFERENCES "core_tag" ("id") DEFERRABLE INITIALLY DEFERRED);
CREATE TABLE IF NOT EXISTS "core_sample_keywords" ("id" integer NOT NULL PRIMARY KEY AUTOINCREMENT, "sample_id" bigint NOT NULL REFERENCES "core_sample" ("id") DEFERRABLE INITIALLY DEFERRED, "keywordvalue_id" bigint NOT NULL REFERENCES "core_keywordvalue" ("id") DEFERRABLE INITIALLY DEFERRED);
CREATE TABLE IF NOT EXISTS "core_samplefile" ("id" integer NOT NULL PRIMARY KEY AUTOINCREMENT, "file" varchar(100) NOT NULL, "description" text NULL, "uploaded_at" datetime NOT NULL, "sample_id" bigint NOT NULL REFERENCES "core_sample" ("id") DEFERRABLE INITIALLY DEFERRED, "mime_type" varchar(100) NULL, "category" varchar(20) NOT NULL, "file_size" bigint NULL);
CREATE TABLE IF NOT EXISTS "core_molecularsequence" ("id" integer NOT NULL PRIMARY KEY AUTOINCREMENT, "name" varchar(255) NOT NULL, "seq_type" varchar(10) NOT NULL, "sequence_data" text NOT NULL, "description" text NOT NULL, "created_at" datetime NOT NULL, "author_id" integer NOT NULL REFERENCES "auth_user" ("id") DEFERRABLE INITIALLY DEFERRED);
CREATE TABLE IF NOT EXISTS "core_notebookentry" ("id" integer NOT NULL PRIMARY KEY AUTOINCREMENT, "title" varchar(255) NOT NULL, "content" text NOT NULL, "created_at" datetime NOT NULL, "updated_at" datetime NOT NULL, "author_id" integer NOT NULL REFERENCES "auth_user" ("id") DEFERRABLE INITIALLY DEFERRED);
CREATE TABLE IF NOT EXISTS "core_notebookentry_mentions" ("id" integer NOT NULL PRIMARY KEY AUTOINCREMENT, "notebookentry_id" bigint NOT NULL REFERENCES "core_notebookentry" ("id") DEFERRABLE INITIALLY DEFERRED, "sample_id" bigint NOT NULL REFERENCES "core_sample" ("id") DEFERRABLE INITIALLY DEFERRED);
CREATE TABLE IF NOT EXISTS "core_chemical" ("id" integer NOT NULL PRIMARY KEY AUTOINCREMENT, "uuid" char(32) NOT NULL UNIQUE, "name" varchar(255) NOT NULL, "formula" varchar(100) NULL, "cas_number" varchar(50) NULL, "quantity" varchar(50) NOT NULL, "expiry_date" date NULL, "location" varchar(255) NULL, "msds_link" varchar(200) NULL, "hazard_notes" text NULL, "status" varchar(20) NOT NULL, "created_at" datetime NOT NULL, "updated_at" datetime NOT NULL, "created_by_id" integer NOT NULL REFERENCES "auth_user" ("id") DEFERRABLE INITIALLY DEFERRED);
CREATE TABLE IF NOT EXISTS "django_session" ("session_key" varchar(40) NOT NULL PRIMARY KEY, "session_data" text NOT NULL, "expire_date" datetime NOT NULL);
CREATE TABLE IF NOT EXISTS "core_biobank" ("id" integer NOT NULL PRIMARY KEY AUTOINCREMENT, "name" varchar(200) NOT NULL, "is_active" bool NOT NULL, "owner_id" integer NOT NULL REFERENCES "auth_user" ("id") DEFERRABLE INITIALLY DEFERRED, "latitude" decimal NULL, "longitude" decimal NULL, "location_label" varchar(255) NOT NULL, "description" text NULL, "research_group_id" bigint NULL REFERENCES "core_researchgroup" ("id") DEFERRABLE INITIALLY DEFERRED, "is_public" bool NOT NULL);
CREATE TABLE IF NOT EXISTS "core_collection" ("id" integer NOT NULL PRIMARY KEY AUTOINCREMENT, "name" varchar(200) NOT NULL, "description" text NULL, "is_active" bool NOT NULL, "biobank_id" bigint NOT NULL REFERENCES "core_biobank" ("id") DEFERRABLE INITIALLY DEFERRED, "owner_id" integer NOT NULL REFERENCES "auth_user" ("id") DEFERRABLE INITIALLY DEFERRED, "created_at" datetime NOT NULL, "updated_at" datetime NOT NULL, "is_public" bool NOT NULL);
CREATE TABLE IF NOT EXISTS "core_bacteria" ("sample_ptr_id" bigint NOT NULL PRIMARY KEY REFERENCES "core_sample" ("id") DEFERRABLE INITIALLY DEFERRED, "species" varchar(150) NOT NULL, "strain" varchar(100) NULL, "genotype" text NULL, "resistance_markers" text NOT NULL CHECK ((JSON_VALID("resistance_markers") OR "resistance_markers" IS NULL)), "additional_info" text NULL);
CREATE TABLE IF NOT EXISTS "core_phage" ("sample_ptr_id" bigint NOT NULL PRIMARY KEY REFERENCES "core_sample" ("id") DEFERRABLE INITIALLY DEFERRED, "morphotype" varchar(50) NULL, "taxonomy" varchar(100) NULL, "lifestyle" varchar(50) NULL, "isolation_source" varchar(255) NULL, "genome_type" varchar(20) NULL, "genome_size_bp" integer unsigned NULL CHECK ("genome_size_bp" >= 0), "ncbi_accession" varchar(100) NULL, "temp_C" decimal NULL, "morphology_img" varchar(100) NULL, "genome_sequence" varchar(100) NULL);
CREATE TABLE IF NOT EXISTS "core_vector" ("sample_ptr_id" bigint NOT NULL PRIMARY KEY REFERENCES "core_sample" ("id") DEFERRABLE INITIALLY DEFERRED, "name_official" varchar(100) NOT NULL, "aliases" text NULL, "vector_type" varchar(50) NULL, "resistance_markers" text NOT NULL CHECK ((JSON_VALID("resistance_markers") OR "resistance_markers" IS NULL)), "induction_system" varchar(100) NULL, "vector_size_bp" integer unsigned NULL CHECK ("vector_size_bp" >= 0), "default_host_id" bigint NULL REFERENCES "core_bacteria" ("sample_ptr_id") DEFERRABLE INITIALLY DEFERRED);
CREATE TABLE IF NOT EXISTS "core_construction" ("sample_ptr_id" bigint NOT NULL PRIMARY KEY REFERENCES "core_sample" ("id") DEFERRABLE INITIALLY DEFERRED, "construction_name" varchar(150) NOT NULL, "insert_name" varchar(100) NULL, "insert_size_bp" integer unsigned NOT NULL CHECK ("insert_size_bp" >= 0), "actual_resistances" text NOT NULL CHECK ((JSON_VALID("actual_resistances") OR "actual_resistances" IS NULL)), "map_file" varchar(100) NULL, "sequence_file" varchar(100) NULL, "origin_lab" varchar(150) NULL, "host_strain_id" bigint NULL REFERENCES "core_bacteria" ("sample_ptr_id") DEFERRABLE INITIALLY DEFERRED, "parent_vector_id" bigint NOT NULL REFERENCES "core_vector" ("sample_ptr_id") DEFERRABLE INITIALLY DEFERRED);
CREATE TABLE IF NOT EXISTS "core_hostrange" ("id" integer NOT NULL PRIMARY KEY AUTOINCREMENT, "is_isolation_host" bool NOT NULL, "efficiency_eop" real NULL, "plaque_morphology" varchar(100) NULL, "bacteria_id" bigint NOT NULL REFERENCES "core_bacteria" ("sample_ptr_id") DEFERRABLE INITIALLY DEFERRED, "phage_id" bigint NOT NULL REFERENCES "core_phage" ("sample_ptr_id") DEFERRABLE INITIALLY DEFERRED);
CREATE TABLE IF NOT EXISTS "core_sample" ("id" integer NOT NULL PRIMARY KEY AUTOINCREMENT, "sample_id" varchar(100) NOT NULL UNIQUE, "sample_type" varchar(100) NULL, "organism_name" varchar(255) NULL, "storage_location" varchar(255) NULL, "notes" text NULL, "created_at" datetime NOT NULL, "biobank_id" bigint NULL REFERENCES "core_biobank" ("id") DEFERRABLE INITIALLY DEFERRED, "collection_id" bigint NULL REFERENCES "core_collection" ("id") DEFERRABLE INITIALLY DEFERRED, "owner_id" integer NOT NULL REFERENCES "auth_user" ("id") DEFERRABLE INITIALLY DEFERRED, "is_active" bool NOT NULL, "status" varchar(20) NOT NULL, "updated_at" datetime NOT NULL, "uuid" char(32) NOT NULL UNIQUE, "scientific_notes" text NULL, "is_public" bool NOT NULL);
DELETE FROM sqlite_sequence;
